var toString=Object.prototype.toString;function stringify(t,r){if(r&&null==t)return r+"=";if("[object Array]"==toString.call(t))return stringifyArray(t,r);if("[object Object]"==toString.call(t))return stringifyObject(t,r);if("[object Date]"==toString.call(t))return t.toISOString();if(r)return r+"="+encodeURIComponent(String(t));if(-1!==String(t).indexOf("="))return String(t);throw new TypeError("Cannot build a querystring out of: "+t)}function stringifyArray(t,r){for(var n=[],i=0,e=t.length;i<e;i++)r?n.push(stringify(t[i],r+"[]")):n.push(stringify(t[i]));return n.join("&")}function stringifyObject(t,r){var n=[];return Object.keys(t).forEach(function(i){n.push(stringify(t[i],r?r+"["+encodeURIComponent(i)+"]":encodeURIComponent(i)))}),n.join("&")}exports.build=stringify;